package vn.edu.fpt.seal.modules.university.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import vn.edu.fpt.seal.modules.university.dto.*; import vn.edu.fpt.seal.modules.university.service.UniversityService; import java.util.UUID;
@RestController @RequiredArgsConstructor public class UniversityController{private final UniversityService service; @GetMapping("/universities") public ResponseEntity<Page<UniversityResponse>> universities(Pageable p){return ResponseEntity.ok(service.universities(p));} @GetMapping("/universities/{id}") public ResponseEntity<UniversityResponse> getUniversity(@PathVariable UUID id){return ResponseEntity.ok(service.getUniversity(id));} @PostMapping("/universities") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<UniversityResponse> createUniversity(@Valid @RequestBody UniversityRequest r){return ResponseEntity.ok(service.createUniversity(r));} @PatchMapping("/universities/{id}") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<UniversityResponse> updateUniversity(@PathVariable UUID id,@Valid @RequestBody UniversityRequest r){return ResponseEntity.ok(service.updateUniversity(id,r));} @DeleteMapping("/universities/{id}") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<Void> deleteUniversity(@PathVariable UUID id){service.deleteUniversity(id); return ResponseEntity.noContent().build();} @GetMapping("/campuses") public ResponseEntity<Page<CampusResponse>> campuses(@RequestParam(required=false) UUID universityId,Pageable p){return ResponseEntity.ok(service.campuses(universityId,p));} @GetMapping("/campuses/{id}") public ResponseEntity<CampusResponse> getCampus(@PathVariable UUID id){return ResponseEntity.ok(service.getCampus(id));} @PostMapping("/campuses") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<CampusResponse> createCampus(@Valid @RequestBody CampusRequest r){return ResponseEntity.ok(service.createCampus(r));} @PatchMapping("/campuses/{id}") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<CampusResponse> updateCampus(@PathVariable UUID id,@Valid @RequestBody CampusRequest r){return ResponseEntity.ok(service.updateCampus(id,r));} @DeleteMapping("/campuses/{id}") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<Void> deleteCampus(@PathVariable UUID id){service.deleteCampus(id); return ResponseEntity.noContent().build();}}
